ini_set('session.use_strict_mode','1');ini_set('session.use_only_cookies','1');session_name('store_setup');session_set_cookie_params(['httponly'=>true,'samesite'=>'Strict','secure'=>$https,'path'=>'/']);session_start();
$_SESSION['setup_csrf']??=bin2hex(random_bytes(32));$error='';$success='';$ready=true;$key='';
function setup_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
try{setup_requirements();$key=setup_key();}catch(Throwable $e){$error='Setup prerequisites are not ready: '.$e->getMessage();$ready=false;}
$input=$_POST;$test=($_POST['action']??'')==='test_db';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'&&$ready){
 try{
  if(!hash_equals($_SESSION['setup_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Setup session expired. Reload the page and try again.');
  if(($_SESSION['setup_attempts']??0)>=10&&($_SESSION['setup_wait']??0)>time())throw new RuntimeException('Too many incorrect setup keys. Wait 15 minutes.');
  if(!hash_equals($key,trim((string)($_POST['setup_key']??'')))){$_SESSION['setup_attempts']=($_SESSION['setup_attempts']??0)+1;$_SESSION['setup_wait']=time()+900;throw new RuntimeException('Incorrect private setup key. Read app/.setup-key.php using your hosting File Manager, not a browser URL.');}
  $_SESSION['setup_attempts']=0;
  if($test){$db=setup_db(setup_db_details($_POST));setup_empty($db);$success='Connected. Database is empty. Final installation will also check schema-creation permissions.';}
  else{setup_run($_POST,$_FILES['logo']??null);$_SESSION=[];session_destroy();header('Location: /#home',true,303);exit;}
 }catch(Throwable $e){$error=$e instanceof PDOException?'Database setup failed. Check permissions; no existing database is overwritten.':$e->getMessage();http_response_code(422);}
}
if($test){header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>$error==='','message'=>$error?:$success]);exit;}
$host=$_SERVER['HTTP_HOST']??'localhost';if(!preg_match('/^[a-zA-Z0-9.\-:\[\]]+$/',$host))$host='localhost';
$defaults=['DB_HOST'=>'localhost','DB_PORT'=>'3306','DB_DATABASE'=>'','DB_USERNAME'=>'','APP_URL'=>($https?'https':'http').'://'.$host,'admin_name'=>'','admin_phone'=>'','shop_name'=>'','mode'=>'clean'];
foreach($defaults as $k=>&$v)if(isset($input[$k])&&is_string($input[$k]))$v=$input[$k];unset($v);
