const form=document.querySelector('#setup-form');if(form){let previewUrl;document.querySelector('#logo').addEventListener('change',e=>{if(previewUrl)URL.revokeObjectURL(previewUrl);const img=document.querySelector('#logo-preview'),file=e.target.files[0];img.hidden=!file;if(file){previewUrl=URL.createObjectURL(file);img.src=previewUrl}});document.querySelector('#test-db').addEventListener('click',async e=>{const b=e.target,result=document.querySelector('#db-result');b.disabled=true;result.textContent='Connecting…';try{const data=new FormData(form);data.delete('logo');data.delete('admin_password');data.delete('admin_confirm');data.set('action','test_db');const response=await fetch('/install.php',{method:'POST',body:data,credentials:'same-origin'});const d=await response.json();result.textContent=d.message;result.className=d.ok?'notice success':'notice error'}catch{result.textContent='Connection test could not complete. Reload if setup has already finished.';result.className='notice error'}finally{b.disabled=false}});form.addEventListener('submit',e=>{if(form.elements.admin_password.value!==form.elements.admin_confirm.value){e.preventDefault();form.elements.admin_confirm.setCustomValidity('Passwords do not match.');form.elements.admin_confirm.reportValidity();return}form.classList.add('busy');document.querySelector('#install-button').disabled=true});form.elements.admin_confirm.addEventListener('input',()=>form.elements.admin_confirm.setCustomValidity(''));}
